const input = $input.first().json.body || $input.first().json;

const outlineId = input.outline_id;
const chaptersData = input.chapters_data || null;

if (!outlineId && !chaptersData) {
  throw new Error('Must provide outline_id or chapters_data');
}

const frontMatter = {
  include_title_page: input.front_matter?.include_title_page !== false,
  include_copyright: input.front_matter?.include_copyright !== false,
  include_toc: input.front_matter?.include_toc !== false,
  copyright_year: input.front_matter?.copyright_year || new Date().getFullYear(),
  copyright_holder: input.front_matter?.copyright_holder || 'Author',
  publisher: input.front_matter?.publisher || 'Self-Published'
};

const backMatter = {
  include_about_author: input.back_matter?.include_about_author || false,
  about_author_text: input.back_matter?.about_author_text || '',
  include_cta: input.back_matter?.include_cta !== false,
  cta_headline: input.back_matter?.cta_headline || 'Want More?',
  cta_text: input.back_matter?.cta_text || '',
  cta_url: input.back_matter?.cta_url || ''
};

return [{
  json: {
    outline_id: outlineId,
    chapters_data: chaptersData,
    front_matter: frontMatter,
    back_matter: backMatter,
    callback_workflow: input.callback_workflow || null,
    session_id: `assemble_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    started_at: new Date().toISOString()
  }
}];

const config = $('Validate & Configure').first().json;
const chapters = config.chapters_data || [];

return [{
  json: {
    ...config,
    outline: {},
    chapters: chapters
  }
}];

const config = $('Validate & Configure').first().json;
const chaptersItems = $('Get Chapters from Table').all();
const outlineItems = $('Get Outline from Table').all();

let chapters = chaptersItems.map(item => item.json);
let outline = outlineItems.length > 0 ? outlineItems[0].json : {};

return [{
  json: {
    ...config,
    outline: outline,
    chapters: chapters
  }
}];

const data = $input.first().json;
const config = data;
const outline = data.outline || {};
let chapters = data.chapters || [];

chapters = chapters.sort((a, b) => (a.section_number || 0) - (b.section_number || 0));

const title = outline.title || 'Untitled Ebook';
const subtitle = outline.subtitle || '';
const format = outline.format || 'ebook';

const totalWords = chapters.reduce((sum, c) => sum + (c.word_count || 0), 0);
const totalSections = chapters.length;
const estimatedPages = Math.ceil(totalWords / 250);
const estimatedReadTime = Math.ceil(totalWords / 200);

const toc = chapters.map(c => ({
  number: c.section_number,
  title: c.title,
  type: c.type
}));

const pageBreak = '\n\n---\n\n';
let document = '';

if (config.front_matter.include_title_page) {
  document += `# ${title}\n\n`;
  if (subtitle) document += `### ${subtitle}\n\n`;
  document += `\n*${estimatedPages} pages • ${estimatedReadTime} minute read*\n\n`;
  document += pageBreak;
}

if (config.front_matter.include_copyright) {
  document += `## Copyright\n\n`;
  document += `© ${config.front_matter.copyright_year} ${config.front_matter.copyright_holder}. All rights reserved.\n\n`;
  document += `Published by ${config.front_matter.publisher}\n\n`;
  document += `No part of this publication may be reproduced, distributed, or transmitted in any form without prior written permission.\n\n`;
  document += pageBreak;
}

if (config.front_matter.include_toc) {
  document += `## Table of Contents\n\n`;
  toc.forEach(item => {
    const prefix = item.type === 'introduction' || item.type === 'conclusion' ? '' : `Chapter ${item.number}: `;
    document += `- [${prefix}${item.title}](#chapter-${item.number})\n`;
  });
  document += pageBreak;
}

chapters.forEach((chapter, index) => {
  document += `<a name="chapter-${chapter.section_number}"></a>\n\n`;
  document += chapter.content || `## ${chapter.title}\n\n[Content not available]`;
  document += '\n\n';
  if (index < chapters.length - 1) {
    document += pageBreak;
  }
});

if (config.back_matter.include_about_author && config.back_matter.about_author_text) {
  document += pageBreak;
  document += `## About the Author\n\n`;
  document += config.back_matter.about_author_text;
  document += '\n\n';
}

if (config.back_matter.include_cta && config.back_matter.cta_text) {
  document += pageBreak;
  document += `## ${config.back_matter.cta_headline}\n\n`;
  document += config.back_matter.cta_text;
  if (config.back_matter.cta_url) {
    document += `\n\n**[Click here to learn more](${config.back_matter.cta_url})**\n\n`;
  }
}

document += `\n\n<!-- \nGenerated: ${new Date().toISOString()}\nTotal Words: ${totalWords}\nSections: ${totalSections}\nSession: ${config.session_id}\nGenerated by Production Line Workflow System\n-->\n`;

return [{
  json: {
    ...config,
    assembled_document: document,
    metadata: {
      title: title,
      subtitle: subtitle,
      format: format,
      total_words: totalWords,
      total_sections: totalSections,
      estimated_pages: estimatedPages,
      estimated_read_time_minutes: estimatedReadTime,
      toc: toc
    }
  }
}];

const data = $input.first().json;
const metadata = data.metadata;

const safeTitle = metadata.title
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 50);

const timestamp = new Date().toISOString().split('T')[0];
const baseFilename = `${safeTitle}_${timestamp}`;

const outputDir = 'C:/dev/production_line/assets/ebooks';
const markdownPath = `${outputDir}/${baseFilename}.md`;

const assetId = `ebook_${data.session_id}`;
const completedAt = new Date().toISOString();
const durationMs = new Date(completedAt) - new Date(data.started_at);

return [{
  json: {
    asset_id: assetId,
    outline_id: data.outline_id,
    session_id: data.session_id,
    markdown_content: data.assembled_document,
    title: metadata.title,
    subtitle: metadata.subtitle,
    format: metadata.format,
    total_words: metadata.total_words,
    total_sections: metadata.total_sections,
    estimated_pages: metadata.estimated_pages,
    estimated_read_time: metadata.estimated_read_time_minutes,
    toc: JSON.stringify(metadata.toc),
    file_path: markdownPath,
    output_directory: outputDir,
    started_at: data.started_at,
    completed_at: completedAt,
    duration_seconds: Math.round(durationMs / 1000),
    callback_workflow: data.callback_workflow,
    status: 'completed'
  }
}];

const assetData = $('Prepare Asset Record').first().json;

return [{
  json: {
    data: Buffer.from(assetData.markdown_content, 'utf-8'),
    fileName: assetData.file_path,
    mimeType: 'text/markdown'
  }
}];

