const data = $('Prepare Asset Record').first().json;

return [{
  json: {
    success: true,
    asset_id: data.asset_id,
    title: data.title,
    subtitle: data.subtitle,
    stats: {
      total_words: data.total_words,
      total_sections: data.total_sections,
      estimated_pages: data.estimated_pages,
      estimated_read_time_minutes: data.estimated_read_time
    },
    file_path: data.file_path,
    storage: 'n8n_data_table',
    duration_seconds: data.duration_seconds,
    ready_for_marketplace: true,
    callback_triggered: !!data.callback_workflow,
    next_steps: [
      `Ebook saved to: ${data.file_path}`,
      'Asset record saved to n8n Data Table',
      'Convert to PDF using pandoc (optional)',
      'Upload to marketplace via W18 workflow'
    ]
  }
}];
